//! Differential corpus generated by the frozen C instrument, not by this port.
use fm1_engine::planner::{bass_event, plan_into, Phrase, Seed, Settings};
use fm1_formats::jam::JamPack;

fn bytes(name: &str) -> &'static [u8] {
    match name {
        "afterhours.jmp" => include_bytes!("packs/afterhours.jmp"),
        "harris-citypop.jmp" => include_bytes!("packs/harris-citypop.jmp"),
        "neon-turnaround.jmp" => include_bytes!("packs/neon-turnaround.jmp"),
        "velvet-changes.jmp" => include_bytes!("packs/velvet-changes.jmp"),
        _ => panic!("unknown reference pack"),
    }
}
fn byte(h: u32, b: u8) -> u32 {
    (h ^ b as u32).wrapping_mul(16_777_619)
}
fn word(mut h: u32, value: u32) -> u32 {
    for b in value.to_le_bytes() {
        h = byte(h, b);
    }
    h
}

#[test]
fn frozen_c_plans_bass_events_and_rng_match() {
    let reference: serde_json::Value =
        serde_json::from_str(include_str!("reference.json")).unwrap();
    let cases = reference["cases"].as_array().unwrap();
    assert_eq!(cases.len(), 192);
    for case in cases {
        let pack = JamPack::parse(bytes(case["pack"].as_str().unwrap())).unwrap();
        let mut h = 2_166_136_261;
        for form in 0..4 {
            for movement in 0..4 {
                let settings = Settings {
                    key: case["key"].as_u64().unwrap() as u8,
                    minor: case["minor"].as_u64().unwrap() as u8,
                    bars: case["bars"].as_u64().unwrap() as u8,
                    form,
                    movement,
                    bass: 3,
                    ..Settings::default()
                };
                let mut seed = Seed::new(4 + form as u32 * 257 + movement as u32 * 4099);
                let mut a = Phrase::EMPTY;
                let mut b = Phrase::EMPTY;
                plan_into(pack, &settings, 0, None, &mut a, &mut seed).unwrap();
                for section in 0..8 {
                    plan_into(pack, &settings, section + 1, Some(&a), &mut b, &mut seed).unwrap();
                    for value in [a.bars, a.role, a.motif, a.section] {
                        h = byte(h, value);
                    }
                    for beat in a.active_beats() {
                        for value in beat.notes {
                            h = byte(h, value);
                        }
                        h = byte(h, beat.node);
                        h = byte(h, beat.passing);
                    }
                    for bar in 0..a.bars as usize {
                        for step in 0..16 {
                            let event = bass_event(pack, &settings, &a, &b, bar, step).unwrap();
                            for value in event.note.to_le_bytes() {
                                h = byte(h, value);
                            }
                            h = byte(h, event.velocity);
                            h = byte(h, event.gate);
                        }
                    }
                    h = word(h, seed.state());
                    a = b;
                }
            }
        }
        assert_eq!(h, case["hash"].as_u64().unwrap() as u32, "{case}");
    }
}

#[test]
fn frozen_c_validation_matches_truncation_extension_and_byte_mutations() {
    let reference: serde_json::Value =
        serde_json::from_str(include_str!("reference.json")).unwrap();
    for case in reference["validation"].as_array().unwrap() {
        let source = bytes(case["pack"].as_str().unwrap());
        let mut data = [0; fm1_types::STORE_MAX + 1];
        data[..source.len()].copy_from_slice(source);
        let mut h = 2_166_136_261;
        let mut accepted = 0;
        for len in 0..=data.len() {
            let valid = JamPack::parse(&data[..len]).is_ok();
            h = byte(h, u8::from(valid));
            accepted += u32::from(valid);
        }
        for i in 0..source.len() {
            for change in [1, 128, 255] {
                data[i] ^= change;
                let valid = JamPack::parse(&data[..source.len()]).is_ok();
                h = byte(h, u8::from(valid));
                accepted += u32::from(valid);
                data[i] ^= change;
            }
        }
        assert_eq!(
            accepted,
            case["accepted"].as_u64().unwrap() as u32,
            "{case}"
        );
        assert_eq!(h, case["hash"].as_u64().unwrap() as u32, "{case}");
    }
}

#[test]
fn arbitrary_inputs_and_bad_settings_do_not_panic() {
    let mut state = 91u32;
    let mut buffer = [0u8; fm1_types::STORE_MAX + 1];
    for round in 0..512 {
        for value in &mut buffer {
            state = state.wrapping_mul(1_664_525).wrapping_add(1_013_904_223);
            *value = (state >> 24) as u8;
        }
        let _ = JamPack::parse(&buffer[..round * 7 % buffer.len()]);
    }
    let pack = JamPack::parse(bytes("afterhours.jmp")).unwrap();
    let invalid = Settings {
        bars: 255,
        ..Settings::default()
    };
    let mut out = Phrase::EMPTY;
    assert!(plan_into(pack, &invalid, 0, None, &mut out, &mut Seed::new(0)).is_err());
}
